hooks.command:
echo \" <<'ADHD_POSIX' >/dev/null # " | Out-Null
try {
  $root = if ($env:CLAUDE_PLUGIN_ROOT) { $env:CLAUDE_PLUGIN_ROOT } else { $env:PLUGIN_ROOT }
  if ($root) {
    $script = Join-Path $root 'hooks/always-on.mjs'
    if (Get-Command node -ErrorAction SilentlyContinue) {
      if (Test-Path -LiteralPath $script) { & node $script }
    } else {
      $script = Join-Path $root 'hooks/always-on.ps1'
      if (Test-Path -LiteralPath $script) { & (Get-Process -Id $PID).Path -NoProfile -ExecutionPolicy Bypass -File $script }
    }
  }
} catch {}
exit 0
<#
ADHD_POSIX
root="${CLAUDE_PLUGIN_ROOT:-$PLUGIN_ROOT}"
[ -n "$root" ] || exit 0
if command -v node >/dev/null 2>&1; then
  [ -f "$root/hooks/always-on.mjs" ] || exit 0
  node "$root/hooks/always-on.mjs"
else
  [ -f "$root/hooks/always-on.sh" ] || exit 0
  sh "$root/hooks/always-on.sh"
fi
exit 0
#>
